const day2Training = window.OMS_EXAM_ARCHIVE.find(item => item.examVersion === '2026-xiamen-shenzhuo-cup-training-selection-day2');
if (day2Training) {
  day2Training.questions.forEach((question, index) => {
    const importedQuestion = day2TrainingPoints[index];
    if (!importedQuestion || !String(question.name || '').startsWith(importedQuestion.letter + '.')) throw Error('Day 2 training point mapping does not match the question order.');
    question.testCases = importedQuestion.cases;
    question.tests = importedQuestion.cases.length;
    question.sampleInput = importedQuestion.cases[0].input;
    question.sampleOutput = importedQuestion.cases[0].expected;
    question.judgeable = true;
    delete question.unjudgeableReason;
  });
}


const numberedExams = [];
for (const exam of [...window.OMS_EXAM_ARCHIVE].filter(item => item.category === 'past')
  .sort((a, b) => Number(a.date) - Number(b.date))) {
  Object.assign(exam, window.OMS_NUMBER_EXAM(exam, numberedExams));
  numberedExams.push(exam);
}
for (const exam of [window.OMS_EXAM_DATA, ...window.OMS_EXAM_ARCHIVE].filter(item => item.category !== 'past')) {
  Object.assign(exam, window.OMS_NUMBER_EXAM(exam, [...numberedExams, exam]));
  numberedExams.push(exam);
}
